// Sensor data eken urgency eka ganna (message eka ain karanna kalin)
let moisture = Number(msg.payload.sensor_data.soil_moisture || 0);
let urgency;
if (moisture <= 30) {
    urgency = "HIGH";
} else if (moisture <= 60) {
    urgency = "MEDIUM";
} else {
    urgency = "LOW";
}

// Message eka extract karanna
msg.payload = msg.payload.care_message;

// Urgency eka msg.urgency ekata danna
msg.urgency = urgency;

// Soil moisture eka msg ekata danna (accuracy chart ekata)
msg.soil_moisture = moisture; 

return msg;

// Timestamp eka hoyaganna - hama thanakin
var ts = null;
if (msg.timestamp !== undefined) {
    ts = msg.timestamp;
} else if (msg.payload && typeof msg.payload === 'object' && msg.payload.timestamp !== undefined) {
    ts = msg.payload.timestamp;
}

// Timestamp eka nathnam - dan time eka ganna
if (ts === null || ts === undefined) {
    msg.payload = new Date().toLocaleString();
    return msg;
}

// Unix timestamp (number) ekak nam
var d;
if (typeof ts === 'number') {
    // Seconds ekak nam * 1000
    if (ts < 10000000000) {
        d = new Date(ts * 1000);
    } else {
        d = new Date(ts);
    }
} else {
    d = new Date(ts);
}

if (isNaN(d.getTime())) {
    d = new Date();
}

msg.payload = d.toLocaleString();
return msg;

// Last message time save කරන්න
flow.set("llm_last_seen", Date.now());

msg.payload = "ONLINE";
return msg;

let lastSeen = flow.get("llm_last_seen") || 0;
let now = Date.now();
let diff = (now - lastSeen) / 1000;

if (lastSeen === 0) {
    msg.payload = "OFFLINE";
} else if (diff > 15) {
    msg.payload = "OFFLINE";
} else {
    msg.payload = "ONLINE";
}

return msg;

flow.set("weather_last_seen", Date.now());
msg.payload = "ONLINE";
return msg;

let lastSeen = flow.get("weather_last_seen") || 0;
let now = Date.now();
let diff = (now - lastSeen) / 1000;

if (diff > 60) {
    msg.payload = "OFFLINE";
} else {
    msg.payload = "ONLINE";
}

return msg;

msg.payload = Number(msg.payload);
msg.topic = "Soil Moisture (%)";
return msg;

let u = String(msg.urgency || '').toUpperCase().trim();

let val = 0;

if (u === "HIGH") {
    val = 100;
} else if (u === "MEDIUM") {
    val = 50;
} else {
    val = 0;
}

msg.payload = val;
msg.topic = "LLM Urgency";
return msg;

// User ge query eka LLM ekata yawanna
msg.payload = {
    device_id: "GreenPulse01",
    query: msg.payload,
    timestamp: Date.now()
};

msg.topic = "greenpulse/GreenPulse01/query";
return msg;

// Get user query
let q = String(msg.payload || "").toLowerCase().trim();
let answer = "";

// Get sensor data from flow context
let soil = flow.get("last_soil") || 0;
let temp = flow.get("last_temp") || 0;
let hum = flow.get("last_hum") || 0;

// Rule-based answers
if (q.indexOf("water") >= 0 || q.indexOf("thirsty") >= 0) {
    if (soil < 30) {
        answer = "Yes, your plant needs watering today. Soil moisture is at " + soil + "%, which is below the healthy threshold of 30%. Water it within the next few hours.";
    } else if (soil < 60) {
        answer = "Your plant is doing okay for now. Soil moisture is at " + soil + "%. Check again in a few hours.";
    } else {
        answer = "No, your plant does not need watering. Soil moisture is at " + soil + "%, which is healthy.";
    }
} else if (q.indexOf("health") >= 0 || q.indexOf("status") >= 0) {
    answer = "Current plant status: Soil moisture " + soil + "%, Temperature " + temp + "°C, Humidity " + hum + "%. Overall: " + (soil < 30 ? "Needs attention" : "Healthy") + ".";
} else if (q.indexOf("temperature") >= 0 || q.indexOf("hot") >= 0 || q.indexOf("cold") >= 0) {
    answer = "Current indoor temperature is " + temp + "°C. ";
    if (temp > 30) answer += "It is quite warm — consider moving the plant away from direct sunlight.";
    else if (temp < 18) answer += "It is a bit cool — keep the plant away from cold drafts.";
    else answer += "This is a comfortable range for most indoor plants.";
} else if (q.indexOf("humidity") >= 0) {
    answer = "Current humidity is " + hum + "%. ";
    if (hum < 40) answer += "Low humidity — consider misting the leaves.";
    else if (hum > 80) answer += "High humidity — ensure good air circulation.";
    else answer += "This is a good range for most indoor plants.";
} else if (q.indexOf("light") >= 0) {
    answer = "Check the Light Status card on your dashboard for the latest light reading.";
} else {
    answer = "I received your question: \"" + msg.payload + "\". Based on current conditions (soil " + soil + "%, temp " + temp + "°C), your plant seems " + (soil < 30 ? "to need attention." : "to be doing well.");
}

msg.payload = answer;
return msg;

// Save sensor data to flow context
flow.set("last_soil", msg.payload.soil_moisture || 0);
flow.set("last_temp", msg.payload.temperature || 0);
flow.set("last_hum",  msg.payload.humidity || 0);

return msg;

let moisture = Number(msg.payload.soil_moisture);

if (moisture <= 30) {
    msg.urgency = "HIGH";
    msg.led_color = "RED";
    msg.backlight = "ON";
} else if (moisture <= 60) {
    msg.urgency = "MEDIUM";
    msg.led_color = "YELLOW";
    msg.backlight = "ON";
} else {
    msg.urgency = "LOW";
    msg.led_color = "GREEN";
    msg.backlight = "OFF";
}

// Urgency widget ekata
let out1 = { payload: msg.urgency };

// MQTT out ekata
let out2 = {
    payload: JSON.stringify({
        device_id: msg.payload.device_id,
        urgency: msg.urgency,
        led_color: msg.led_color,
        backlight: msg.backlight,
        timestamp: msg.payload.timestamp
    }),
    topic: "greenpulse/GreenPulse01/urgency"
};

return [out1, out2];

// Extract sunlight_level from payload
msg.payload = msg.payload.sunlight_level;
return msg;
